import fs from 'node:fs';
import path from 'node:path';

const migrationsDir = path.join(process.cwd(), 'migrations');
if (!fs.existsSync(migrationsDir)) {
  console.warn(`[Migrations Codegen] Migrations directory not found at ${migrationsDir}`);
  process.exit(0);
}

const files = fs.readdirSync(migrationsDir).filter((f) => f.endsWith('.sql')).sort();

let content = `/**
 * @file embeddedMigrations.ts
 * ====================================================================================
 * AUTO-GENERATED FILE - DO NOT EDIT DIRECTLY!
 *
 * Source of Truth: migrations/*.sql
 * Generated by   : npm run db:generate-migrations (scripts/generate-embedded-migrations.ts)
 *
 * Embeds SQL migration scripts into the bundle for universal runtime execution
 * in serverless environments (Cloudflare Workers) where the filesystem is inaccessible.
 * ====================================================================================
 */

export const EMBEDDED_MIGRATIONS: Record<string, string> = {
`;

for (const file of files) {
  const filePath = path.join(migrationsDir, file);
  const sql = fs.readFileSync(filePath, 'utf-8');
  content += `  ${JSON.stringify(file)}: ${JSON.stringify(sql)},\n`;
}

content += `};\n`;

const outPath = path.join(process.cwd(), 'src/lib/turso/embeddedMigrations.ts');
fs.writeFileSync(outPath, content, 'utf-8');
console.log(`[Migrations Codegen] Successfully synchronized ${files.length} migrations from migrations/ to ${outPath} (${(content.length / 1024).toFixed(1)} KB)`);
